mapper.select:
SELECT status
FROM tl_meetings
WHERE meetings_id = #{meetingId}

mapper.insert:
INSERT INTO tl_meeting_documents (
    meeting_id, doc_id, doc_type, added_by_user_id
) VALUES (
    #{meetingId}, #{docId}, 'ORIGINAL', #{addedByUserId}
)

INSERT INTO tl_meeting_documents (
  meeting_id, trans_doc_id, doc_type, added_by_user_id
) VALUES (
  #{meetingId}, #{transDocId}, 'TRANSLATION', #{addedByUserId} 
)

mapper.delete:
DELETE FROM tl_meeting_documents
WHERE meeting_id = #{meetingId}
  AND doc_id = #{docId}
  AND doc_type = 'ORIGINAL'

DELETE FROM tl_meeting_documents
WHERE meeting_id = #{meetingId}
  AND trans_doc_id = #{transDocId}
  AND doc_type = 'TRANSLATION'

mapper.select:
SELECT COUNT(*)
FROM tl_documents
WHERE doc_id = #{docId}
  AND uploader_user_id = #{userId}

SELECT COUNT(*)
FROM tl_trans_docs td
INNER JOIN tl_documents d ON td.original_doc_id = d.doc_id
WHERE td.trans_doc_id = #{transDocId}
  AND d.uploader_user_id = #{userId}
